        t, v = data["pids"]["0C"]["t"], data["pids"]["0C"]["v"]
        self.assertEqual(len(t), len(v))

    def test_synthetic_banner(self):
        self.assertIn("SYNTH DATA", self.html)


if __name__ == "__main__":
    unittest.main()
